      "number": 2,
      "stem": "甲公司經營牧場，於 X1 年 10 月 2 日購進 20 頭小乳牛，待成齡後可以生產牛乳出售，每頭小乳牛購進價格$100,000，另支付運費與檢疫費用合計$24,000，若將這20 頭小乳牛立刻出售，將須支付出售成本$12,000，運費由買方負擔。則甲公司 X1 年 10 月 2 日應認列「生物資產當期公允價值減出售成本之變動之利益」金額為何？",
