      "subject": "accounting",
      "sourceId": "accounting-04",
      "number": 13,
      "stem": "甲公司於X1年底以$1,000,000(含交易成本)買入乙公司三年期無追索權的公司債(分類為按攤銷後成本衡量之投資)，面額$1,000,000、票面利率 3%，每年 12 月 31 日付息一次，有關該公司債的預期信用損失估計金額如下： 12 個月預期信用損失存續期間預期信用損失 X1 年底 $ 5,000 $ 12,000 X2 年底 $ 26,000 $ 50,000 X3 年底 $ 160,000 $ 160,000 於 X2年底，甲公司判定該債券的信用風險已顯著增加，且 X3 年底該債券已自活絡市場中消失，達到減損的地步，則甲公司於 X1、X2、X3 年底應認列之減損損失金額各應為何？",
