      "stem": "甲公司於X1 年初成立，X1 年底有二項關於所得稅會計處理之暫時性差異：(1) X1年底認列產品保固負債準備$8,000,000，產品保固的相關成本將於 X2 年發生及支付；(2) X1 年底報稅時採用縮短耐用年限申報之折舊費用超過帳上折舊數$4,800,000。假設各年度的稅率均為 20%，甲公司 X1 年度的課稅所得為$256,000,000，包括當年度因交際費超限應剔除之金額$1,280,000，甲公司預計未來有足夠的課稅所得可供遞延所得稅資產迴轉使用。則甲公司 X1 年度綜合損益表應列報的所得稅費用金額為何？",
