      "sourceId": "law-01",
      "number": 13,
      "stem": "A 公司為上市公司，設有董事 7 人，其中3 人為獨立董事，並組成審計委員會。若 A 公司擬向其董事甲購買土地一筆，該議案於審計委員會討論時，未獲通過。依證券交易法規定，下列敘述何者正確？",
      "options": [
        "該議案得由全體董事過半數以上同意行之，並將審計委員會決議，載明於董事會議事錄",
        "該議案不得提請董事會討論",
        "該議案得由全體董事三分之二以上同意行之，並將審計委員會決議，載明於董事會議事錄",
        "該議案應由全體董事出席，出席董事四分之三以上同意始可通過，並將審計委員會決議，載明於董事會議事錄"
      ],
      "answer": [
        "C"
      ],
      "sourceIds": [
        "law-01"
      ],
      "sourceRefs": [
        {
          "chapterId": "law-01",
          "sectionIndex": 1
        }
      ]
