      "year": 108,
      "session": 3,
      "subject": "law",
      "sourceId": "law-03",
      "number": 14,
      "stem": "公開發行股票之公司於登記後，應即將其董事、監察人、經理人及持有股份超過股份總額百分之十之股東，所持有之本公司股票種類及股數，向主管機關申報並公告之，其後股數變動應如何處理？",
      "options": [
        "應於每月五日以前將上月份持有股數變動之情形，向公司申報，公司應於每月十五日以前，彙總向主管機關申報",
        "應於每月十日以前將上月份持有股數變動之情形，向公司申報，公司應於每月十五日以前，彙總向主管機關申報",
        "應於每月十五日以前將上月份持有股數變動之情形，向公司申報，公司應於每月二十日以前，彙總向主管機關申報",
        "應於每月十五日以前將上月份持有股數變動之情形，向公司申報，公司應於每月三十日以前，彙總向主管機關申報"
      ],
