        "違反或不履行辦理募集與發行有價證券時所出具之承諾，情節重大者",
        "上市、上櫃公司或興櫃股票公司未依證券交易法第十四條之六第一項規定設置薪資報酬委員會或未依相關法令規定辦理，情節重大者"
