      "session": 4,
      "subject": "investment",
      "sourceId": "investment-06",
      "number": 11,
      "stem": "張三在某上市公司財務部擔任重要職務，可接觸該公司第一手消息（甚至比老闆還快） ，在上週開會確定公司可調高盈餘目標時，張三即打電話叫進股票，但一週來該上市公司股票卻無任何激情的表現，張三根本占不到便宜。試問市場效率之程度？",
