      "subject": "investment",
      "sourceId": "investment-07",
      "number": 12,
      "stem": "一個三年期，每年付息一次並重設票息的浮動利率債券，在發行時的票面利率為 Index + 5.5%。假設在發行三個月後，市場指標利率下跌為 4.5%，債券信用風險維持不變，則此債券的存續期間約為多少？",
